<?php
declare(strict_types=1);
namespace App\Services;
use PDO; use RuntimeException;
final class MatchReportService { public function __construct(private PDO $db) {} public function score(int $matchId): array {$s=$this->db->prepare("SELECT team_id,event_type,metadata_json FROM match_events WHERE match_id=? AND is_cancelled=0 AND deleted_at IS NULL AND event_type IN ('goal','own_goal')");$s->execute([$matchId]);$m=$this->db->prepare('SELECT home_team_id,away_team_id FROM matches WHERE id=?');$m->execute([$matchId]);$match=$m->fetch();$score=['home'=>0,'away'=>0];foreach($s as $e){$side=(int)$e['team_id']===(int)$match['home_team_id']?'home':'away';if($e['event_type']==='own_goal')$side=$side==='home'?'away':'home';$score[$side]++;}return $score;} public function addEvent(int $matchId,array $data,?int $userId): int {$s=$this->db->prepare('INSERT INTO match_events(match_id,team_id,person_id,assist_person_id,event_type,minute,period,metadata_json,version_number,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,1,?,NOW(),NOW())');$s->execute([$matchId,$data['team_id']??null,$data['person_id']??null,$data['assist_person_id']??null,$data['event_type'],$data['minute']??null,$data['period']??null,json_encode($data['metadata']??[]),$userId]);$id=(int)$this->db->lastInsertId();$score=$this->score($matchId);$this->db->prepare('UPDATE matches SET home_score=?,away_score=?,updated_at=NOW() WHERE id=?')->execute([$score['home'],$score['away'],$matchId]);return $id;} public function cancelEvent(int $id,string $reason,?int $userId): void {if($reason==='')throw new RuntimeException('Motivo obrigatório.');$s=$this->db->prepare('SELECT match_id FROM match_events WHERE id=? AND is_cancelled=0');$s->execute([$id]);$row=$s->fetch();if(!$row)throw new RuntimeException('Evento inválido.');$this->db->prepare('UPDATE match_events SET is_cancelled=1,correction_reason=?,updated_at=NOW() WHERE id=?')->execute([$reason,$id]);$score=$this->score((int)$row['match_id']);$this->db->prepare('UPDATE matches SET home_score=?,away_score=?,updated_at=NOW() WHERE id=?')->execute([$score['home'],$score['away'],$row['match_id']]);} }
